const UNITS = { h: 3600000, m: 60000, s: 1000, ms: 1 };

export function parseDuration(text) {
  if (typeof text !== 'string' || text.length === 0) {
    throw new Error(`bad duration: ${text}`);
  }
  let total = 0;
  let pos = 0;
  while (pos < text.length) {
    const numMatch = /^\d+/.exec(text.slice(pos));
    if (!numMatch) throw new Error(`bad duration: ${text}`);
    const num = Number(numMatch[0]);
    pos += numMatch[0].length;
    const unitMatch = /^(h|m|s|ms)/.exec(text.slice(pos));
    if (!unitMatch) throw new Error(`bad duration: ${text}`);
    total += num * UNITS[unitMatch[0]];
    pos += unitMatch[0].length;
  }
  return total;
}

