export function parseCsvLine(line) {
  const fields = [];
  let current = '';
  let i = 0;

  while (i < line.length) {
    if (line[i] === '"') {
      // Start of quoted field
      i++;
      while (i < line.length) {
        if (line[i] === '"') {
          if (i + 1 < line.length && line[i + 1] === '"') {
            // Escaped quote
            current += '"';
            i += 2;
          } else {
            // End of quoted field
            i++;
            break;
          }
        } else {
          current += line[i];
          i++;
        }
      }
      // After a quoted field, consume trailing comma or finish
      if (i < line.length && line[i] === ',') {
        fields.push(current);
        current = '';
        i++;
      } else if (i === line.length) {
        fields.push(current);
        current = '';
      }
    } else if (line[i] === ',') {
      // End of unquoted field
      fields.push(current);
      current = '';
      i++;
    } else {
      current += line[i];
      i++;
    }
  }

  // Push last field (handles trailing comma and end-of-line)
  fields.push(current);

  return fields;
}

