const ROMAN_MAP = [
  [1000, 'M'], [900, 'CM'], [500, 'D'], [400, 'CD'],
  [100, 'C'], [90, 'XC'], [50, 'L'], [40, 'XL'],
  [10, 'X'], [9, 'IX'], [5, 'V'], [4, 'IV'], [1, 'I']
];

export function toRoman(n) {
  if (!Number.isInteger(n) || n < 1 || n > 3999) {
    throw new RangeError('n must be an integer between 1 and 3999');
  }
  let result = '';
  for (const [value, numeral] of ROMAN_MAP) {
    while (n >= value) {
      result += numeral;
      n -= value;
    }
  }
  return result;
}

export function fromRoman(s) {
  if (typeof s !== 'string') {
    throw new Error('Invalid Roman numeral');
  }
  const input = s.toUpperCase();
  const romanToValue = Object.fromEntries(ROMAN_MAP.map(([v, n]) => [n, v]));
  let total = 0;
  let i = 0;
  while (i < input.length) {
    const twoChar = input.slice(i, i + 2);
    if (romanToValue[twoChar] !== undefined) {
      total += romanToValue[twoChar];
      i += 2;
    } else {
      const oneChar = input[i];
      if (romanToValue[oneChar] === undefined) {
        throw new Error('Invalid Roman numeral');
      }
      total += romanToValue[oneChar];
      i += 1;
    }
  }
  // Validate: re-convert to ensure it's the canonical form
  if (toRoman(total) !== input) {
    throw new Error('Invalid Roman numeral');
  }
  return total;
}

